        "observation": "@Secured({ROLE_CUSTOMERGROUP, ROLE_CUSTOMERMANAGERGROUP, ROLE_TRUSTED_CLIENT}), @PostMapping(value, consumes = APPLICATION_JSON_VALUE), @ResponseBody, @ResponseStatus(HttpStatus.OK), @Operation(operationId, summary, description), @ApiBaseSiteIdAndUserIdParam.",
